-- Bundle 38 (2026-10-26): add the pipes and fittings, precast elements and civil basics (excavation, reinforced concrete, blockwork and plaster) starter estimate templates, and the illustrative catalogue items they price their materials from. Run AFTER migrations 0131, 0213 and 0098. No new migration. Safe to re-run. Run on dev and production.
-- Starter estimate templates (the chain-link fence, the tiles, porta cabin and GCC starters, and the catalogue fields of the others)
-- and the illustrative catalogue items the GCC starters (pipes, precast elements, civil basics) price their materials from.
-- Run AFTER supabase/migrations/0131_estimator.sql and 0213_estimate_template_catalogue.sql; the catalogue items need 0098 (products).
-- Idempotent: a template is added if the workspace has none of that name; a workspace's own
-- editable template is never changed; the LOCKED starters are refreshed to the current ones. A catalogue item is added only when the
-- workspace has no product with that SKU, so an item edited or repriced from a rate sheet is never overwritten.
-- GENERATED by scripts/gen-estimate-seeds.ts from src/lib/estimator/starterTemplates.ts; do not
-- edit by hand, change that file and regenerate.
--
-- WHO GETS IT: every DEMO tenant (is_demo = true) that has the estimator module on.
--
-- ONE OTHER WORKSPACE (for example a client that has the estimator module): either press
-- "Add the ... starter" in that workspace's Settings > Estimate templates (no SQL; it adds the catalogue items too),
-- or change the single line marked TARGET below to
--     select id from tenants where slug = '<the workspace slug>' and coalesce((features->>'estimator')::boolean, false)
-- and run it. A live client is never targeted by this file as shipped.

do $seed$
declare
  t uuid;
  seq int;
  item record;
begin
  if not exists (select 1 from information_schema.columns where table_name = 'estimate_templates' and column_name = 'locked') then
    raise exception 'Run supabase/migrations/0213_estimate_template_catalogue.sql first (estimate_templates.locked is missing).';
  end if;
  if to_regclass('public.estimate_templates') is null then
    raise exception 'Run supabase/migrations/0131_estimator.sql first.';
  end if;

  for t in -- TARGET
    select id from tenants where is_demo = true and coalesce((features->>'estimator')::boolean, false)
  loop

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Pipes and fittings (illustrative)')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules, keywords, icon, locked, customer_visible)
      values (
        t, 'Pipes and fittings (illustrative)', 'ILLUSTRATIVE starter for a buried pipeline in steel, GRP or HDPE: excavation, bedding, pipe, fittings and valves, joints, laying, pressure test, backfill and surface reinstatement, with the cost per metre and the totals. Pipe and fitting costs come from catalogue items marked illustrative until you import a rate sheet; plant and labour rates are placeholders. Copy it and replace them with your own.', 'pipelines', '', 1, true, 'group',
        $inputs$[{"key":"pipe_material","label":"Pipe material","type":"select","default":"steel","options":[{"key":"steel","label":"Steel, coated","value":1,"attrs":{"pipe_material":"steel"}},{"key":"grp","label":"GRP","value":2,"attrs":{"pipe_material":"grp"}},{"key":"hdpe","label":"HDPE (PE100)","value":3,"attrs":{"pipe_material":"hdpe"}}],"help":"Picks the pipe, fittings and joints from your catalogue, and how long a joint takes to make.","section":"Pipeline"},{"key":"pipe_dn","label":"Nominal diameter","type":"select","default":"dn300","options":[{"key":"dn100","label":"DN 100","value":100,"attrs":{"pipe_dn":"100"}},{"key":"dn200","label":"DN 200","value":200,"attrs":{"pipe_dn":"200"}},{"key":"dn300","label":"DN 300","value":300,"attrs":{"pipe_dn":"300"}},{"key":"dn400","label":"DN 400","value":400,"attrs":{"pipe_dn":"400"}},{"key":"dn600","label":"DN 600","value":600,"attrs":{"pipe_dn":"600"}}],"unit":"mm","section":"Pipeline"},{"key":"length_m","label":"Pipeline length","type":"number","default":1000,"min":1,"max":100000,"unit":"m","section":"Pipeline"},{"key":"fittings_n","label":"Fittings (bends, tees, reducers)","type":"number","default":10,"min":0,"max":5000,"unit":"nr","section":"Fittings and valves"},{"key":"valves_n","label":"Valves","type":"number","default":2,"min":0,"max":1000,"unit":"nr","section":"Fittings and valves"},{"key":"depth_m","label":"Trench depth","type":"number","default":1.8,"min":1,"max":8,"unit":"m","help":"Average depth from the ground to the bottom of the trench.","section":"Trench"},{"key":"soil_type","label":"Soil","type":"select","default":"sand","options":[{"key":"sand","label":"Sand or loose soil","value":1},{"key":"clay","label":"Stiff clay","value":1.4},{"key":"rock","label":"Rock","value":2.5}],"help":"Clay digs slower than sand, and rock needs a breaker as well as the excavator.","section":"Trench"},{"key":"surface","label":"Surface to reinstate","type":"select","default":"natural","options":[{"key":"natural","label":"Natural ground (none)","value":0},{"key":"gravel","label":"Gravel","value":1,"attrs":{"surface":"gravel"}},{"key":"asphalt","label":"Asphalt","value":2,"attrs":{"surface":"asphalt"}}],"section":"Trench"}]$inputs$::jsonb,
        $rates$[{"key":"trench_clearance_m","label":"Working space each side of the pipe","unit":"m","value":0.3},{"key":"bed_thickness_m","label":"Bedding under and over the pipe","unit":"m","value":0.15},{"key":"exc_m3_per_h","label":"Excavator production in sand","unit":"m³/h","value":25},{"key":"excavator_rate_hr","label":"Excavator with operator","unit":"per h","value":145,"low":130,"high":175},{"key":"breaker_h_per_m3","label":"Breaker time in rock","unit":"h/m³","value":0.15},{"key":"breaker_rate_hr","label":"Hydraulic breaker with operator","unit":"per h","value":190,"low":170,"high":230},{"key":"backfill_cost_m3","label":"Backfill and compaction, labour and plant","unit":"per m³","value":18,"low":15,"high":24},{"key":"spoil_swell","label":"Loose volume of spoil per m³ in place","unit":"factor","value":1.25},{"key":"spoil_cart_cost_m3","label":"Spoil carted to tip","unit":"per m³","value":14,"low":12,"high":19},{"key":"pipe_length_m","label":"Length of one pipe","unit":"m","value":12},{"key":"deliv_load_m_dn300","label":"Metres of DN 300 pipe on one delivery","unit":"m/load","value":120},{"key":"delivery_cost_load","label":"Delivery of pipe, per load","unit":"per load","value":900,"low":800,"high":1150},{"key":"lay_h_per_m","label":"Gang hours to lay one metre of DN 300","unit":"h/m","value":0.35,"low":0.3,"high":0.5},{"key":"lay_crew_rate_hr","label":"Pipe gang (foreman, fitter, two labourers)","unit":"per h","value":85,"low":75,"high":105},{"key":"lay_plant_rate_hr","label":"Laying plant (side boom or excavator)","unit":"per h","value":160,"low":140,"high":200},{"key":"joint_h_steel","label":"Hours to weld and coat one steel joint","unit":"h","value":2.5},{"key":"joint_h_grp","label":"Hours to make one GRP coupling","unit":"h","value":1.2},{"key":"joint_h_hdpe","label":"Hours to make one HDPE electrofusion joint","unit":"h","value":1.5},{"key":"test_section_m","label":"Length of one pressure-test section","unit":"m","value":500},{"key":"test_cost_section","label":"Pressure test of one section (pump, water, gauges, crew)","unit":"per section","value":2400,"low":2000,"high":3200},{"key":"overhead_factor","label":"Overhead (share of all the cost above)","unit":"fraction","value":0.1}]$rates$::jsonb,
        $rules$[{"code":"exc","group":"31 23 16 Excavation","description":"Trench excavation (excavator with operator)","uom":"h","qty":"length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m * soil_type / exc_m3_per_h","component":"other","cost":{"kind":"rate","rate":"excavator_rate_hr"}},{"code":"rock","group":"31 23 16 Excavation","description":"Rock breaking (hydraulic breaker)","uom":"h","qty":"(soil_type > 2) * length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m * breaker_h_per_m3","component":"other","cost":{"kind":"rate","rate":"breaker_rate_hr"}},{"code":"bed","group":"31 23 23 Bedding and backfill","description":"Granular bedding and surround","uom":"m3","qty":"length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * min(depth_m, 2 * bed_thickness_m + pipe_dn / 1000)","waste_pct":5,"component":"materials","cost":{"kind":"product","sku":"EST-PIPE-BED"}},{"code":"bkf","group":"31 23 23 Bedding and backfill","description":"Backfill and compaction (labour and plant)","uom":"m3","qty":"max(0, length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m - qty_bed)","component":"other","cost":{"kind":"rate","rate":"backfill_cost_m3"}},{"code":"spl","group":"31 23 23 Bedding and backfill","description":"Surplus spoil carted to tip (bedding and pipe take the room of soil)","uom":"m3","qty":"(qty_bed + length_m * 0.7854 * (pipe_dn / 1000) * (pipe_dn / 1000)) * spoil_swell","component":"transport","cost":{"kind":"rate","rate":"spoil_cart_cost_m3"}},{"code":"pipe","group":"33 11 00 Pipe, fittings and valves","description":"Pipe, supplied","uom":"m","qty":"length_m","waste_pct":2,"component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_supply"},"from":["pipe_material","pipe_dn"]}}},{"code":"fit","group":"33 11 00 Pipe, fittings and valves","description":"Fittings (bends, tees, reducers)","uom":"nr","qty":"fittings_n","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_fitting"},"from":["pipe_material","pipe_dn"]}}},{"code":"val","group":"33 11 00 Pipe, fittings and valves","description":"Isolation valves","uom":"nr","qty":"valves_n","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_valve"},"from":["pipe_dn"]}}},{"code":"jnt","group":"33 11 00 Pipe, fittings and valves","description":"Joints (one between pipes, two at every fitting and valve)","uom":"nr","qty":"max(0, ceil(length_m / pipe_length_m) - 1) + 2 * (fittings_n + valves_n)","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_joint"},"from":["pipe_material","pipe_dn"]}}},{"code":"dlv","group":"33 11 00 Pipe, fittings and valves","description":"Delivery of pipe to site (loads by diameter)","uom":"load","qty":"ceil(length_m * pipe_dn / (deliv_load_m_dn300 * 300))","component":"transport","cost":{"kind":"rate","rate":"delivery_cost_load"}},{"code":"lay","group":"33 11 00 Laying, jointing and testing","description":"Laying pipe (pipe gang)","uom":"h","qty":"length_m * lay_h_per_m * pipe_dn / 300","component":"labour","cost":{"kind":"rate","rate":"lay_crew_rate_hr"}},{"code":"layp","group":"33 11 00 Laying, jointing and testing","description":"Laying plant (side boom or excavator)","uom":"h","qty":"qty_lay","component":"other","cost":{"kind":"rate","rate":"lay_plant_rate_hr"}},{"code":"jlab","group":"33 11 00 Laying, jointing and testing","description":"Jointing labour","uom":"h","qty":"qty_jnt * if(pipe_material == 1, joint_h_steel, if(pipe_material == 2, joint_h_grp, joint_h_hdpe))","component":"labour","cost":{"kind":"rate","rate":"lay_crew_rate_hr"}},{"code":"tst","group":"33 11 00 Laying, jointing and testing","description":"Hydrostatic pressure test (per section)","uom":"section","qty":"ceil(length_m / test_section_m)","component":"other","cost":{"kind":"rate","rate":"test_cost_section"}},{"code":"rein","group":"Surface reinstatement","description":"Surface reinstatement over the trench","uom":"m2","qty":"(surface > 0) * length_m * (pipe_dn / 1000 + 2 * trench_clearance_m)","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"reinstatement"},"from":["surface"]}}},{"code":"ovh","group":"Overhead","description":"Overhead","uom":"cost","qty":"sub_31_23_16_excavation + sub_31_23_23_bedding_and_backfill + sub_33_11_00_pipe_fittings_and_valves + sub_33_11_00_laying_jointing_and_testing + sub_surface_reinstatement","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb,
        array['pipe', 'pipes', 'pipeline', 'piping', 'water main', 'main', 'steel pipe', 'GRP', 'HDPE', 'PE100', 'ductile', 'fittings', 'valves', 'trench', 'trenching', 'laying', 'jointing', 'pressure test', 'hydrotest', 'backfill', 'reinstatement', 'network', 'irrigation', 'sewer', 'per metre']::text[], 'grid', true, false
      );
    else
