bel":"Natural ground (none)","value":0},{"key":"gravel","label":"Gravel","value":1,"attrs":{"surface":"gravel"}},{"key":"asphalt","label":"Asphalt","value":2,"attrs":{"surface":"asphalt"}}],"section":"Trench"}]$inputs$::jsonb,
