al","options":[{"key":"natural","label":"Natural ground (none)","value":0},{"key":"gravel","label":"Gravel","value":1,"attrs":{"surface":"gravel"}},{"key":"asphalt","label":"Asphalt","value":2,"attrs":{"surface":"asphalt"}}],"section":"Trench"}]$inputs$::jsonb or rules is distinct from $rules$[{"code":"exc","group":"31 23 16 Excavation","description":"Trench excavation (excavator with operator)","uom":"h","qty":"length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m * soil_type / exc_m3_per_h","component":"other","cost":{"kind":"rate","rate":"excavator_rate_hr"}},{"code":"rock","group":"31 23 16 Excavation","description":"Rock breaking (hydraulic breaker)","uom":"h","qty":"(soil_type > 2) * length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m * breaker_h_per_m3","component":"other","cost":{"kind":"rate","rate":"breaker_rate_hr"}},{"code":"bed","group":"31 23 23 Bedding and backfill","description":"Granular bedding and surround","uom":"m3","qty":"length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * min(depth_m, 2 * bed_thickness_m + pipe_dn / 1000)","waste_pct":5,"component":"materials","cost":{"kind":"product","sku":"EST-PIPE-BED"}},{"code":"bkf","group":"31 23 23 Bedding and backfill","description":"Backfill and compaction (labour and plant)","uom":"m3","qty":"max(0, length_m * (pipe_dn / 1000 + 2 * trench_clearance_m) * depth_m - qty_bed)","component":"other","cost":{"kind":"rate","rate":"backfill_cost_m3"}},{"code":"spl","group":"31 23 23 Bedding and backfill","description":"Surplus spoil carted to tip (bedding and pipe take the room of soil)","uom":"m3","qty":"(qty_bed + length_m * 0.7854 * (pipe_dn / 1000) * (pipe_dn / 1000)) * spoil_swell","component":"transport","cost":{"kind":"rate","rate":"spoil_cart_cost_m3"}},{"code":"pipe","group":"33 11 00 Pipe, fittings and valves","description":"Pipe, supplied","uom":"m","qty":"length_m","waste_pct":2,"component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_supply"},"from":["pipe_material","pipe_dn"]}}},{"code":"fit","group":"33 11 00 Pipe, fittings and valves","description":"Fittings (bends, tees, reducers)","uom":"nr","qty":"fittings_n","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_fitting"},"from":["pipe_material","pipe_dn"]}}},{"code":"val","group":"33 11 00 Pipe, fittings and valves","description":"Isolation valves","uom":"nr","qty":"valves_n","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_valve"},"from":["pipe_dn"]}}},{"code":"jnt","group":"33 11 00 Pipe, fittings and valves","description":"Joints (one between pipes, two at every fitting and valve)","uom":"nr","qty":"max(0, ceil(length_m / pipe_length_m) - 1) + 2 * (fittings_n + valves_n)","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"pipe_joint"},"from":["pipe_material","pipe_dn"]}}},{"code":"dlv","group":"33 11 00 Pipe, fittings and valves","description":"Delivery of pipe to site (loads by diameter)","uom":"load","qty":"ceil(length_m * pipe_dn / (deliv_load_m_dn300 * 300))","component":"transport","cost":{"kind":"rate","rate":"delivery_cost_load"}},{"code":"lay","group":"33 11 00 Laying, jointing and testing","description":"Laying pipe (pipe gang)","uom":"h","qty":"length_m * lay_h_per_m * pipe_dn / 300","component":"labour","cost":{"kind":"rate","rate":"lay_crew_rate_hr"}},{"code":"layp","group":"33 11 00 Laying, jointing and testing","description":"Laying plant (side boom or excavator)","uom":"h","qty":"qty_lay","component":"other","cost":{"kind":"rate","rate":"lay_plant_rate_hr"}},{"code":"jlab","group":"33 11 00 Laying, jointing and testing","description":"Jointing labour","uom":"h","qty":"qty_jnt * if(pipe_material == 1, joint_h_steel, if(pipe_material == 2, joint_h_grp, joint_h_hdpe))","component":"labour","cost":{"kind":"rate","rate":"lay_crew_rate_hr"}},{"code":"tst","group":"33 11 00 Laying, jointing and testing","description":"Hydrostatic pressure test (per section)","uom":"section","qty":"ceil(length_m / test_section_m)","component":"other","cost":{"kind":"rate","rate":"test_cost_section"}},{"code":"rein","group":"Surface reinstatement","description":"Surface reinstatement over the trench","uom":"m2","qty":"(surface > 0) * length_m * (pipe_dn / 1000 + 2 * trench_clearance_m)","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"reinstatement"},"from":["surface"]}}},{"code":"ovh","group":"Overhead","description":"Overhead","uom":"cost","qty":"sub_31_23_16_excavation + sub_31_23_23_bedding_and_backfill + sub_33_11_00_pipe_fittings_and_valves + sub_33_11_00_laying_jointing_and_testing + sub_surface_reinstatement","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb then version + 1 else version end
      where tenant_id = t and lower(name) = lower('Pipes and fittings (illustrative)') and locked = true;
